from .alphavantage import AlphaVantage as av


class SectorPerformances(av):
    """Compatibility shim: provide SectorPerformances with a get_sector method.

    This mirrors older alpha_vantage wrappers expected by some packages.
    """

    def __init__(self, *args, **kwargs):
        super(SectorPerformances, self).__init__(*args, **kwargs)
        self._append_type = False

    @av._output_format_sector
    @av._call_api_on_func
    def get_sector(self, output_format='json'):
        _FUNCTION_KEY = "SECTOR"
        # The Alpha Vantage JSON uses multiple keys for sector outputs; the wrapper
        # decorator handles formatting. Provide a sensible placeholder for the
        # data and meta keys expected by the decorator.
        return _FUNCTION_KEY, 'Rank A: Real-Time Performance', 'Meta Data'
